!function(){"use strict";var e=window.IWACVis;e&&e.addTranslations&&(e.addTranslations("en",{"Loading press language metrics":"Loading press language metrics","lexical.mean_readability":"Average readability (Flesch)","lexical.mean_richness":"Average lexical richness","lexical.mean_words":"Average words per article","lexical.readability_title":"Readability over time","lexical.readability_desc":"Average Flesch reading-ease score (French adaptation) of the articles published each year, computed from the scanned text. The higher the score, the easier the article is to read.","lexical.richness_title":"Lexical richness over time","lexical.richness_desc":"Average lexical richness of the articles published each year, computed from the scanned text. The measure is MATTR, which counts how many different words appear in each 50-word stretch of an article. The higher the value, the more varied the vocabulary. MATTR holds steady as an article gets longer, so long and short articles are directly comparable; articles under 50 words are left unscored.","lexical.words_title":"Article length over time","lexical.words_desc":"Average number of words per article published each year, counted from the scanned text.","lexical.np_read_title":"Newspapers by readability","lexical.np_read_desc":"Newspapers with at least {min} articles, ranked by their average Flesch reading-ease score, computed from the scanned text (top {top}). The higher the score, the easier the articles are to read.","lexical.np_rich_title":"Newspapers by lexical richness","lexical.np_rich_desc":"Newspapers with at least {min} articles, ranked by their average lexical richness (MATTR), computed from the scanned text (top {top}). The higher the value, the more varied the vocabulary.","lexical.axis_readability":"Flesch score","lexical.axis_richness":"MATTR"}),e.addTranslations("fr",{"Loading press language metrics":"Chargement des indicateurs de langue","lexical.mean_readability":"Lisibilité moyenne (Flesch)","lexical.mean_richness":"Richesse lexicale moyenne","lexical.mean_words":"Mots par article (moyenne)","lexical.readability_title":"Lisibilité au fil du temps","lexical.readability_desc":"Score moyen de lisibilité Flesch (adaptation française) des articles publiés chaque année, calculé à partir du texte numérisé. Plus le score est élevé, plus l’article est facile à lire.","lexical.richness_title":"Richesse lexicale au fil du temps","lexical.richness_desc":"Richesse lexicale moyenne des articles publiés chaque année, calculée à partir du texte numérisé. La mesure employée, le MATTR, compte le nombre de mots différents dans chaque fenêtre de 50 mots de l’article. Plus la valeur est élevée, plus le vocabulaire est varié. Le MATTR ne varie pas avec la longueur de l’article, si bien que les articles longs et courts sont directement comparables ; ceux de moins de 50 mots ne sont pas notés.","lexical.words_title":"Longueur des articles au fil du temps","lexical.words_desc":"Nombre moyen de mots par article publié chaque année, compté à partir du texte numérisé.","lexical.np_read_title":"Journaux par lisibilité","lexical.np_read_desc":"Journaux comptant au moins {min} articles, classés par score moyen de lisibilité Flesch calculé à partir du texte numérisé (top {top}). Plus le score est élevé, plus les articles sont faciles à lire.","lexical.np_rich_title":"Journaux par richesse lexicale","lexical.np_rich_desc":"Journaux comptant au moins {min} articles, classés par richesse lexicale moyenne (MATTR) calculée à partir du texte numérisé (top {top}). Plus la valeur est élevée, plus le vocabulaire est varié.","lexical.axis_readability":"Score Flesch","lexical.axis_richness":"MATTR"}))}();